#!/usr/bin/env python3
import datetime as dt,html,importlib.util,json,os,sqlite3,subprocess,time
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from urllib.parse import parse_qs,urlparse
from zoneinfo import ZoneInfo
DB=os.getenv('PAPER_AGENT_DB','/var/lib/paper-agent/paper-agent.db');PORT=int(os.getenv('PAPER_AGENT_PORT','8088'));NZ=ZoneInfo('Pacific/Auckland');QUOTE_TTL=60
def dbopen(path=DB):
 d=sqlite3.connect(path,timeout=10);d.row_factory=sqlite3.Row;d.execute('PRAGMA busy_timeout=10000');return d
def has(d,name):return d.execute("select 1 from sqlite_master where type='table' and name=?",(name,)).fetchone() is not None
def utc(v):
 if not v:return None
 value=str(v).strip();parts=value.split()
 if len(parts)>=4 and parts[0][:3].title() in ('Mon','Tue','Wed','Thu','Fri','Sat','Sun'):value=' '.join(parts[1:])
 if value.endswith(' UTC'):value=value[:-4]+'+00:00'
 try:x=dt.datetime.fromisoformat(value.replace('Z','+00:00'))
 except ValueError:return None
 return x if x.tzinfo else x.replace(tzinfo=dt.timezone.utc)
def nz(v):
 x=utc(v);return x.astimezone(NZ).strftime('%d %b %Y, %-I:%M:%S %p %Z') if x else 'Unavailable'
def money(v):return 'Unavailable' if v is None else f'${float(v):,.2f}'
def pct(v):return 'Unavailable' if v is None else f'{float(v):+,.2%}'
def esc(v):return html.escape(str(v if v is not None else '—'))
def timer_times():
 try:
  p=subprocess.run(['systemctl','show','paper-agent-broad.timer','-p','LastTriggerUSec','-p','NextElapseUSecRealtime','--no-pager'],capture_output=True,text=True,timeout=2);x=dict(line.split('=',1) for line in p.stdout.splitlines() if '=' in line);return nz(x.get('LastTriggerUSec')),nz(x.get('NextElapseUSecRealtime'))
 except Exception:return 'Unavailable','Unavailable'
def quote_module():
 p='/opt/paper-agent/app/experiment_execution.py';s=importlib.util.spec_from_file_location('_q',p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
def quote(d,ticker,watch):
 row=d.execute('select price,source,quoted_at,updated_epoch from quote_cache where ticker=?',(ticker,)).fetchone() if has(d,'quote_cache') else None
 if row and time.time()-float(row['updated_epoch'])<=QUOTE_TTL:return dict(price=row['price'],source=row['source'],quoted_at=row['quoted_at'],stale=False)
 try:q=quote_module().resolve_quote(d,watch,ticker);q['stale']=False;return q
 except Exception:return dict(price=row['price'],source=str(row['source'])+' cached',quoted_at=row['quoted_at'],stale=True) if row else dict(price=None,source='UNAVAILABLE',quoted_at=None,stale=True)
def target(d,event,opened,entry):
 r=d.execute('select max_days,profit_target,stop_loss from event_exit_rules where event_type=?',(event,)).fetchone() if has(d,'event_exit_rules') else None;days,profit,stop=(tuple(r) if r else (10,.15,.10));x=utc(opened) or dt.datetime.now(dt.timezone.utc);left=days
 while left:
  x+=dt.timedelta(days=1)
  if x.weekday()<5:left-=1
 return dict(days=days,target=entry*(1+profit),stop=entry*(1-stop),exit=x.isoformat())
def snapshot(path=DB,limit=100,ticker='',status='',source='',event='',refresh=True):
 d=dbopen(path);watch={}
 try:
  with open('/etc/paper-agent/watchlist.json',encoding='utf-8') as f:watch=json.load(f)
 except Exception:pass
 positions=[];q='''select p.id,p.ticker,p.theme,p.opened,p.entry_price,p.shares,p.cost,p.status,p.decision_id,x.created decision_time,x.score,x.reason,n.source,n.title,n.url,t.event_type from positions p join decisions x on x.id=p.decision_id left join news n on n.uid=x.news_uid left join theses t on t.decision_id=x.id where p.status='OPEN' order by p.opened desc'''
 for r in d.execute(q):
  z=dict(r);qq=quote(d,z['ticker'],watch) if refresh else dict(price=z['entry_price'],source='TEST',quoted_at=z['opened'],stale=False);price=qq.get('price');mv=price*float(z['shares']) if price else None;pnl=mv-float(z['cost']) if mv is not None else None;tg=target(d,z.get('event_type') or 'general_news',z['opened'],float(z['entry_price']));z.update(current=price,quote_source=qq.get('source'),quote_at=qq.get('quoted_at'),stale=qq.get('stale'),market_value=mv,pnl=pnl,pnl_pct=pnl/float(z['cost']) if pnl is not None else None,**tg);positions.append(z)
 cashrow=d.execute('select balance from ledger order by id desc limit 1').fetchone();cash=float(cashrow[0]) if cashrow else 0;cost=sum(float(x['cost']) for x in positions);market=sum(float(x['market_value'] if x['market_value'] is not None else x['cost']) for x in positions);where=['1=1'];args=[]
 if ticker:where.append('x.ticker like ?');args.append('%'+ticker.upper()+'%')
 if status:where.append('x.status=?');args.append(status)
 if source:where.append("coalesce(n.source,'') like ?");args.append('%'+source+'%')
 if event:where.append("coalesce(t.event_type,'')=?");args.append(event)
 args.append(limit);decisions=[dict(r) for r in d.execute(f'''select x.id,x.created,x.ticker,x.action,x.score,x.status,x.reason,x.rules_version,x.entry_price,x.shares,x.amount,x.theme,n.source,n.title,n.summary,n.url,n.published,t.event_type,t.thesis_json,t.model_version from decisions x left join news n on n.uid=x.news_uid left join theses t on t.decision_id=x.id where {' and '.join(where)} order by x.id desc limit ?''',args)];counts=dict(d.execute('select status,count(*) from decisions group by status').fetchall());last,next_=timer_times();integrity=d.execute('pragma quick_check').fetchone()[0];champion=dict(d.execute("select * from strategy_versions where status='CHAMPION' order by created desc limit 1").fetchone()) if has(d,'strategy_versions') and d.execute("select 1 from strategy_versions where status='CHAMPION'").fetchone() else None;readiness=dict(d.execute('select * from market_readiness order by id desc limit 1').fetchone()) if has(d,'market_readiness') and d.execute('select 1 from market_readiness').fetchone() else None;rec=dict(d.execute('select * from daily_reconciliation order by created desc limit 1').fetchone()) if has(d,'daily_reconciliation') and d.execute('select 1 from daily_reconciliation').fetchone() else None;challengers=[dict(x) for x in d.execute('select * from challenger_results order by created desc limit 8')] if has(d,'challenger_results') else [];recommendations=[dict(x) for x in d.execute('select * from strategy_recommendations order by created desc limit 5')] if has(d,'strategy_recommendations') else [];d.close();return dict(cash=cash,cost=cost,market=market,equity=cash+market,pnl=market-cost,positions=positions,decisions=decisions,counts=counts,last=last,next=next_,integrity=integrity,champion=champion,readiness=readiness,reconciliation=rec,challengers=challengers,recommendations=recommendations,generated=nz(dt.datetime.now(dt.timezone.utc).isoformat()))
CSS='''<style>:root{--bg:#07111e;--panel:#0d1b2a;--panel2:#102338;--line:#243a51;--text:#eaf1f8;--muted:#8fa7bc;--blue:#48a8ff;--green:#37d69a;--red:#ff6875;--amber:#ffc85b;--gold:#ffd166}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:13px system-ui,-apple-system,sans-serif}.top{position:sticky;top:0;z-index:20;background:#081522;border-bottom:1px solid var(--line);padding:10px 18px;display:flex;align-items:center;gap:18px}.brand{font-weight:850;font-size:15px}.jump{display:flex;gap:5px;flex-wrap:wrap}.jump a{color:var(--muted);text-decoration:none;padding:7px 9px;border-radius:6px}.jump a:hover{color:white;background:var(--panel2)}.clock{margin-left:auto;text-align:right;color:var(--muted);font-size:11px}main{max-width:1800px;margin:auto;padding:16px}.hero{display:flex;justify-content:space-between;align-items:end;margin:4px 0 12px}.hero h1{margin:0;font-size:23px}.hero small{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(7,minmax(130px,1fr));gap:8px}.card{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:12px;min-height:80px}.card.highlight{border:2px solid var(--gold);background:#26210f;box-shadow:0 0 0 1px #5d4b1c inset}.card span{display:block;color:var(--muted);text-transform:uppercase;font-size:10px;letter-spacing:.06em}.card strong{display:block;font-size:19px;margin-top:7px}.card.highlight strong{font-size:23px;color:var(--gold)}.pos{color:var(--green)!important}.neg{color:var(--red)!important}.warn{color:var(--amber)!important}.section{scroll-margin-top:65px;margin-top:18px}.section-title{display:flex;justify-content:space-between;align-items:end;margin:0 0 8px}.section-title h2{font-size:16px;margin:0}.section-title small{color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:12px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:9px;background:var(--panel)}table{border-collapse:collapse;width:100%;min-width:1200px}th,td{padding:10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{position:sticky;top:0;background:#10253a;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.05em}tr:hover td{background:#102238}td small{display:block;color:var(--muted);margin-top:4px;line-height:1.35}.cost{color:var(--gold);font-size:15px;font-weight:850}.pnl{font-size:15px;font-weight:850}.tag,.score{display:inline-block;border-radius:999px;padding:3px 7px;border:1px solid var(--line);font-size:10px}.s90{background:#087f5b}.s80{background:#175c91}.s60{background:#875e12}.s0{background:#6d2834}.filters{display:flex;flex-wrap:wrap;gap:7px}.filters input,.filters select,.filters button{background:#102238;color:var(--text);border:1px solid var(--line);border-radius:6px;padding:7px 9px}.filters button{background:#174b75}.two{display:grid;grid-template-columns:1.25fr .75fr;gap:9px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}details{border-top:1px solid var(--line)}details:first-child{border-top:0}summary{cursor:pointer;padding:10px;color:var(--blue);font-weight:700}.detail{padding:0 10px 12px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.mini{background:#091725;padding:9px;border-radius:7px}.mini b{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;margin-bottom:5px}.mini pre{white-space:pre-wrap;word-break:break-word;margin:0;font:11px ui-monospace;color:#cbd7e3}.bar{height:7px;background:#081522;border-radius:9px;overflow:hidden;margin-top:6px}.bar i{display:block;height:100%;background:var(--blue)}.statusline{display:flex;gap:14px;flex-wrap:wrap}.statusline b{color:var(--muted)}a{color:var(--blue)}footer{color:var(--muted);padding:20px 0}.empty{text-align:center;color:var(--muted);padding:22px}@media(max-width:1100px){.cards{grid-template-columns:repeat(3,1fr)}.two,.three{grid-template-columns:1fr}.clock{display:none}}@media(max-width:600px){main{padding:9px}.cards{grid-template-columns:repeat(2,1fr)}.top{position:static}.jump{display:none}.detail{grid-template-columns:1fr}}</style>'''
def jsonpretty(v):
 try:return json.dumps(json.loads(v),indent=2,sort_keys=True) if isinstance(v,str) else json.dumps(v,indent=2,sort_keys=True,default=str)
 except Exception:return str(v or 'Unavailable')
def render(data,params):
 pnlcls='pos' if data['pnl']>=0 else 'neg';cards=''.join([
  f'<div class="card"><span>Portfolio equity</span><strong>{money(data["equity"])}</strong></div>',f'<div class="card"><span>Cash available</span><strong>{money(data["cash"])}</strong></div>',f'<div class="card highlight"><span>Total capital buy price</span><strong>{money(data["cost"])}</strong></div>',f'<div class="card"><span>Current market value</span><strong>{money(data["market"])}</strong></div>',f'<div class="card"><span>Unrealised P&amp;L</span><strong class="{pnlcls}">{money(data["pnl"])}</strong></div>',f'<div class="card"><span>Open positions</span><strong>{len(data["positions"])}</strong></div>',f'<div class="card"><span>Database / mode</span><strong>{esc(data["integrity"])} · {"PAUSED" if os.path.exists("/var/lib/paper-agent/PAUSE_TRADES") else "ACTIVE"}</strong></div>'])
 prows=''
 for x in data['positions']:
  pc='pos' if (x['pnl'] or 0)>=0 else 'neg';stale=' · STALE' if x['stale'] else ''
  prows+=f'''<tr><td><b>{esc(x['ticker'])}</b><small>{esc(x['theme'])} · {esc(x['event_type'] or 'general_news')}</small></td><td>{nz(x['opened'])}<small>Decision {nz(x['decision_time'])}</small></td><td>{money(x['entry_price'])}<small>{int(x['shares']):,} shares</small><div class="cost">{money(x['cost'])}</div><small>Total capital buy price</small></td><td>{money(x['current'])}<small>{esc(x['quote_source'])}{stale}<br>{nz(x['quote_at'])}</small></td><td>{money(x['market_value'])}</td><td><span class="pnl {pc}">{money(x['pnl'])}</span><small class="{pc}">{pct(x['pnl_pct'])}</small></td><td>{money(x['target'])}<small>Stop {money(x['stop'])}</small></td><td>{nz(x['exit'])}<small>{x['days']} trading days</small></td><td><span class="score s{90 if x['score']>=90 else 80 if x['score']>=80 else 60 if x['score']>=65 else 0}">{x['score']:.0f}</span><small>{esc(x['source'])}</small></td></tr>'''
 if not prows:prows='<tr><td colspan="9" class="empty">No open virtual positions</td></tr>'
 drows='';detail=''
 for x in data['decisions']:
  band=90 if float(x['score'] or 0)>=90 else 80 if float(x['score'] or 0)>=80 else 60 if float(x['score'] or 0)>=65 else 0
  drows+=f'''<tr><td>{nz(x['created'])}</td><td><b>{esc(x['ticker'])}</b><small>{esc(x['theme'])}</small></td><td>{esc(x['action'])}</td><td><span class="score s{band}">{float(x['score'] or 0):.0f}</span></td><td><span class="tag">{esc(x['status'])}</span></td><td>{esc(x['event_type'])}</td><td>{esc(x['source'])}</td><td><details><summary>Inspect decision #{x['id']}</summary><div class="detail"><div class="mini"><b>Event evidence</b><strong>{esc(x['title'])}</strong><p>{esc(x['summary'])}</p><a href="{esc(x['url'])}" target="_blank">Open source</a><small>Published {nz(x['published'])}</small></div><div class="mini"><b>Decision logic</b><pre>{esc(jsonpretty(x['reason']))}</pre></div><div class="mini"><b>Thesis / version</b><pre>{esc(jsonpretty(x['thesis_json']))}</pre><small>Model {esc(x['model_version'])} · Rules {esc(x['rules_version'])}</small></div></div></details></td></tr>'''
 filters=f'''<form class="filters" method="get" action="#decisions"><input name="ticker" value="{esc(params['ticker'])}" placeholder="Ticker"><input name="source" value="{esc(params['source'])}" placeholder="Source"><select name="status"><option value="">All statuses</option>{''.join(f'<option value="{s}"'+(' selected' if params['status']==s else '')+f'>{s}</option>' for s in ['EXECUTED','REJECTED','BASELINE','AWAITING_PRICE','CAPACITY_DEFERRED','NO_PRICE','EXECUTION_ERROR'])}</select><input name="event" value="{esc(params['event'])}" placeholder="Event type"><select name="limit">{''.join(f'<option value="{n}"'+(' selected' if params['limit']==n else '')+f'>{n} decisions</option>' for n in [50,100,250,500])}</select><button>Apply filters</button><a href="/#decisions">Reset</a></form>'''
 champion=data['champion'];strategy=(f'<pre>{esc(jsonpretty(champion.get("logic_json")))}</pre><small>Version {esc(champion.get("version"))} · Git {esc(champion.get("git_commit"))} · logic hash {esc(champion.get("logic_hash"))}</small>' if champion else '<p class="warn">Strategy registry not yet populated. Champion remains the active V3 strategy.</p>')
 learning='<pre>'+esc(jsonpretty({'challengers':data['challengers'],'recommendations':data['recommendations']}))+'</pre>'
 operations='<div class="statusline"><span><b>Last collector</b> '+esc(data['last'])+'</span><span><b>Next collector</b> '+esc(data['next'])+'</span><span><b>Generated</b> '+esc(data['generated'])+'</span></div><pre>'+esc(jsonpretty({'market_readiness':data['readiness'],'reconciliation':data['reconciliation'],'decision_status_counts':data['counts']}))+'</pre>'
 return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="60"><title>Paper Agent Trader Command Centre</title>{CSS}</head><body><div class="top"><div class="brand">PAPER AGENT · VIRTUAL TRADER</div><nav class="jump"><a href="#portfolio">Portfolio</a><a href="#positions">Positions</a><a href="#decisions">Decisions</a><a href="#strategy">Strategy</a><a href="#learning">Learning</a><a href="#operations">Operations</a></nav><div class="clock">NZ time<br>{esc(data['generated'])}</div></div><main><div class="hero"><div><h1>Trader command centre</h1><small>Single-page portfolio, decisions, strategy, research and operations · refreshes every 60 seconds</small></div></div><section id="portfolio" class="cards">{cards}</section><section id="positions" class="section"><div class="section-title"><h2>Open virtual positions</h2><small>Prices, capital at cost, mark-to-market P&amp;L and strategy exits</small></div><div class="tablewrap"><table><thead><tr><th>Position</th><th>Opened NZT</th><th>Entry / capital buy</th><th>Latest quote</th><th>Market value</th><th>Unrealised P&amp;L</th><th>Target / stop</th><th>Estimated exit NZT</th><th>Signal</th></tr></thead><tbody>{prows}</tbody></table></div></section><section id="decisions" class="section"><div class="section-title"><h2>Decision ledger</h2><small>{len(data['decisions'])} displayed · expandable evidence and logic</small></div><div class="panel">{filters}</div><div class="tablewrap"><table><thead><tr><th>Decision NZT</th><th>Ticker</th><th>Action</th><th>Score</th><th>Status</th><th>Event</th><th>Source</th><th>Audit detail</th></tr></thead><tbody>{drows}</tbody></table></div></section><div class="two"><section id="strategy" class="section panel"><div class="section-title"><h2>Active strategy</h2><small>Frozen champion logic</small></div>{strategy}</section><section id="learning" class="section panel"><div class="section-title"><h2>Learning and challengers</h2><small>Recommendations never auto-promote</small></div>{learning}</section></div><section id="operations" class="section panel"><div class="section-title"><h2>Operations, readiness and reconciliation</h2><small>Collector schedule shown in Pacific/Auckland</small></div>{operations}</section><footer>Virtual research system only. Estimated exits and targets are strategy outputs, not guarantees. Quote source, timestamp and stale status are shown for every open position.</footer></main></body></html>'''
class H(BaseHTTPRequestHandler):
 def log_message(self,*a):pass
 def send(self,code,body,ctype='text/html; charset=utf-8'):
  b=body.encode();self.send_response(code);self.send_header('Content-Type',ctype);self.send_header('Content-Length',str(len(b)));self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(b)
 def do_GET(self):
  try:
   q=parse_qs(urlparse(self.path).query);raw=(q.get('limit') or ['100'])[0];limit=int(raw) if raw.isdigit() else 100;limit=max(50,min(500,limit));params=dict(limit=limit,ticker=(q.get('ticker') or [''])[0],status=(q.get('status') or [''])[0],source=(q.get('source') or [''])[0],event=(q.get('event') or [''])[0])
   if urlparse(self.path).path=='/health':return self.send(200,json.dumps({'ok':True,'version':'3.5.2-single-page'}),'application/json')
   return self.send(200,render(snapshot(limit=limit,ticker=params['ticker'],status=params['status'],source=params['source'],event=params['event']),params))
  except Exception as e:return self.send(500,'Dashboard error: '+esc(type(e).__name__+': '+str(e)))
if __name__=='__main__':ThreadingHTTPServer(('0.0.0.0',PORT),H).serve_forever()
